# -*- coding: utf-8 -*-
"""ابتكارات التجارة الإلكترونية - الدفعة الثالثة."""
from biz_tools import F, S, add, CATS, T

add('cod-risk-scorer', 'ecom', '🚨', 'مقيّم مخاطر الدفع عند الاستلام', 'درجة مخاطرة طلب الدفع عند الاستلام (COD) وقرار: قبول/تأكيد/عربون.',
 [F('v', 'قيمة الطلب', 'n', 450), F('n', 'عدد طلبات العميل السابقة المستلمة', 'n', 0), F('r', 'عدد الطلبات المرفوضة/المرتجعة سابقًا', 'n', 1), S('c', 'تأكد رقم الجوال؟', [('1', 'نعم (واتساب/اتصال)'), ('0', 'لا')]), S('a', 'العنوان واضح وكامل؟', [('1', 'نعم'), ('0', 'ناقص/غامض')]), S('t', 'وقت الطلب', [('0', 'عادي'), ('1', 'بعد منتصف الليل/عروض ضخمة')])],
 r'''function compute(v){let s=0;s+=v.v>800?25:v.v>400?12:4;s+=v.n>=2?-10:v.n===0?10:0;s+=v.r*18;s+=v.c==='1'?-12:18;s+=v.a==='1'?-5:15;s+=v.t==='1'?8:0;s=Math.max(0,Math.min(100,s+15));const d=s<30?['قبول مباشر','good']:s<60?['تأكيد بالاتصال قبل الشحن','']:['عربون أو دفع مسبق','bad'];return kpis([kpi('درجة المخاطرة',f(s,0)+'/100',d[1]),kpi('القرار المقترح',d[0],d[1])])+rec(['أكد كل طلبات COD فوق 400 بواتساب قبل الشحن.','اعرض خصمًا صغيرًا للدفع المسبق لخفض الرفض.','سجل قائمة سوداء داخلية للأرقام ذات الرفض المتكرر.'])+note('قاعدة تقديرية وليست نظام احتيال. عدّل الأوزان حسب بيانات متجرك.')}''')

add('returns-profit-impact', 'ecom', '↩️', 'أثر المرتجعات على الأرباح', 'كم تكلفك نسبة المرتجعات فعلًا؟',
 [F('o', 'عدد الطلبات الشهرية', 'n', 500), F('p', 'متوسط سعر الطلب', 'n', 200), F('m', 'هامش الربح قبل المرتجع %', 'n', 35), F('r', 'نسبة المرتجعات %', 'n', 12), F('s', 'تكلفة شحن الإرجاع للطلب', 'n', 25), F('l', 'نسبة المرتجع غير القابل لإعادة البيع %', 'n', 20)],
 r'''function compute(v){const rev=v.o*v.p,ret=v.o*v.r/100,lostRev=ret*v.p,profit=rev*v.m/100,cost=ret*v.s+ret*(v.l/100)*v.p*(1-v.m/100),net=profit-lostRev*v.m/100-cost;return kpis([kpi('الربح النظري',f(profit)),kpi('إيراد ضائع',f(lostRev),'bad'),kpi('تكلفة الإرجاع والتلف',f(cost),'bad'),kpi('الربح الصافي بعد المرتجعات',f(net),net<0?'bad':'good')])+rec(['خفض المرتجعات 3 نقاط يرفع الربح بقيمة تقارب '+f(v.o*0.03*(v.p*v.m/100+v.s),0)+' شهريًا.','حسّن جدول المقاسات والصور فهما أكبر مسببات الإرجاع.','اجمع سبب الإرجاع في قائمة واضحة وحلل أكثرها تكرارًا.'])}''')

add('coupon-breakeven', 'ecom', '🎟️', 'حاسبة ربحية الكوبون', 'كم زيادة في الطلبات تحتاج ليعوّض الخصم؟',
 [F('p', 'سعر المنتج', 'n', 200), F('c', 'تكلفة المنتج + الشحن', 'n', 120), F('d', 'نسبة الخصم %', 'n', 15), F('o', 'عدد الطلبات الحالية شهريًا', 'n', 300)],
 r'''function compute(v){const m0=v.p-v.c,m1=v.p*(1-v.d/100)-v.c;if(m1<=0)return'<b>الخصم يلغي الهامش: خسارة في كل طلب.</b>';const need=v.o*m0/m1;return kpis([kpi('هامش قبل الخصم',f(m0)),kpi('هامش بعد الخصم',f(m1),m1<m0*0.5?'bad':''),kpi('طلبات لازمة للتعادل',f(Math.ceil(need),0),'good'),kpi('زيادة مطلوبة',f((need/v.o-1)*100,0)+'%','bad')])+rec(['الخصم '+v.d+'% يتطلب زيادة '+f((need/v.o-1)*100,0)+'% في الطلبات لتعوّضه؛ جرّب خصمًا أقل أو حدًا أدنى للطلب.','استخدم كوبونًا لفئة محددة بدل الجميع.','حدد مدة قصيرة لخلق الاستعجال.'])}''')

add('price-change-simulator', 'ecom', '📊', 'محاكي تغيير السعر', 'هل ترفع السعر أم تخفضه؟ جرّب أثر المبيعات على الربح.',
 [F('p', 'السعر الحالي', 'n', 100), F('c', 'التكلفة للوحدة', 'n', 60), F('q', 'المبيعات الشهرية (وحدات)', 'n', 1000), F('ch', 'التغير المقترح في السعر %', 'n', 10), F('e', 'مرونة الطلب (تقدير)', 'n', -1.2, h='-1 قليلة، -2 عالية')],
 r'''function compute(v){const np=v.p*(1+v.ch/100),nq=v.q*(1+v.e*v.ch/100),p0=(v.p-v.c)*v.q,p1=(np-v.c)*nq;return kpis([kpi('السعر الجديد',f(np)),kpi('المبيعات المتوقعة',f(nq,0)),kpi('ربح قبل',f(p0)),kpi('ربح بعد',f(p1),p1>=p0?'good':'bad')])+rec([p1>=p0?'التغيير يرفع الربح ضمن هذه الفروض.':'التغيير يخفض الربح: جرّب نسبة أصغر.','اختبر السعر الجديد على جزء من الزوار (A/B) قبل التعميم.','المرونة تقدير: اختبرها بالواقع.'])}''')

add('flash-sale-planner', 'ecom', '⚡', 'مخطط العرض الخاطف', 'مخزون، مدة، خصم ← الإيراد والربح المتوقع.',
 [F('s', 'مخزون العرض (وحدات)', 'n', 300), F('p', 'السعر العادي', 'n', 150), F('d', 'الخصم %', 'n', 25), F('c', 'التكلفة للوحدة', 'n', 80), F('h', 'مدة العرض (ساعات)', 'n', 24), F('a', 'إنفاق الإعلان على العرض', 'n', 2000), F('r', 'نسبة بيع المخزون المتوقعة %', 'n', 70)],
 r'''function compute(v){const sp=v.p*(1-v.d/100),u=v.s*v.r/100,rev=u*sp,prof=u*(sp-v.c)-v.a;return kpis([kpi('سعر العرض',f(sp)),kpi('الوحدات المباعة',f(u,0)),kpi('الإيراد',f(rev)),kpi('الربح بعد الإعلان',f(prof),prof>=0?'good':'bad'),kpi('وحدات/ساعة',f(u/v.h,1))])+rec([prof<0?'العرض خاسر بهذه الفروض: ارفع نسبة البيع أو خفض الخصم أو الإنفاق.':'العرض مربح بهذه الفروض.','حدد مخزونًا محدودًا لبناء الندرة الحقيقية.','جهز الشحن والخدمة لحجم الطلبات قبل البدء.'])}''')

add('abandoned-cart-roi', 'ecom', '🛒', 'عائد استرداد السلات المتروكة', 'قدّر ما يضيفه تذكير السلة المتروكة للإيراد.',
 [F('v', 'زوار السلة شهريًا', 'n', 3000), F('a', 'نسبة ترك السلة %', 'n', 70), F('r', 'نسبة الاسترداد بالتذكير %', 'n', 8), F('o', 'متوسط قيمة السلة', 'n', 220), F('m', 'هامش الربح %', 'n', 30), F('c', 'تكلفة أداة/رسائل شهريًا', 'n', 300)],
 r'''function compute(v){const ab=v.v*v.a/100,rec_=ab*v.r/100,rev=rec_*v.o,pr=rev*v.m/100-v.c;return kpis([kpi('سلال متروكة',f(ab,0)),kpi('طلبات مستردة',f(rec_,0),'good'),kpi('إيراد إضافي',f(rev),'good'),kpi('ربح صافٍ بعد التكلفة',f(pr),pr>=0?'good':'bad')])+rec(['أرسل أول تذكير بعد ساعة وثانيًا بعد 24 ساعة.','أضف عنصر أمان: شحن مجاني أو ضمان إرجاع.','لا ترسل كوبونًا من أول رسالة.'])}''')

add('rfm-segmenter', 'ecom', '🧩', 'مقسّم العملاء RFM', 'الصق عملاءك (اسم | أيام منذ آخر شراء | عدد الطلبات | الإنفاق) فتُصنَّف شرائحهم.',
 [F('t', 'العملاء', 'textarea', 'سارة | 12 | 8 | 4200\nأحمد | 95 | 3 | 900\nنورة | 220 | 1 | 150\nخالد | 25 | 5 | 2300\nريم | 400 | 2 | 500\nفهد | 5 | 1 | 200', r=8)],
 r'''function compute(v){const L=lines(v.t).map(r=>({n:r[0],d:num(r[1]),o:num(r[2]),m:num(r[3])}));if(!L.length)return'';const seg=c=>{if(c.d<=45&&c.o>=5)return['🏆 أبطال','قدّم لهم مزايا حصرية وبرنامج ولاء'];if(c.d<=45&&c.o>=2)return['💚 أوفياء ناشئون','اقترح منتجات مكملة'];if(c.d<=45)return['🆕 جدد','رسالة ترحيب ومتابعة بعد الشراء الأول'];if(c.d>180)return['😴 مفقودون','حملة استرجاع بعرض قوي'];if(c.o>=3)return['⚠️ على وشك الرحيل','تواصل شخصي وعرض خاص'];return['🌙 هادئون','تذكير بمنتجات جديدة']};const rows=L.map(c=>{const s=seg(c);return[esc(c.n),c.d,c.o,f(c.m,0),s[0],s[1]]});const g={};L.forEach(c=>{const s=seg(c)[0];g[s]=(g[s]||0)+c.m});return tbl(['العميل','أيام','طلبات','الإنفاق','الشريحة','الإجراء'],rows)+tbl(['الشريحة','إجمالي الإنفاق'],Object.keys(g).map(k=>[k,f(g[k],0)]))+aiOut('أنت خبير CRM. لدي شرائح عملاء: '+Object.keys(g).join('، ')+'. اكتب لكل شريحة رسالة واتساب من 40 كلمة وعرضًا مناسبًا.')}''', ai=True)

add('marketplace-fees-compare', 'ecom', '🏬', 'مقارنة رسوم القنوات: متجرك مقابل المنصات', 'الربح الصافي لنفس المنتج عبر قنوات بيع بعمولات مختلفة.',
 [F('p', 'سعر البيع', 'n', 200), F('c', 'التكلفة (منتج+تغليف)', 'n', 100), F('f1', 'عمولة المنصة A %', 'n', 12), F('f2', 'عمولة المنصة B %', 'n', 8), F('g', 'رسوم الدفع في متجرك %', 'n', 2.5), F('s', 'تكلفة شحن للطلب', 'n', 20), F('a', 'تكلفة اكتساب العميل في متجرك', 'n', 25)],
 r'''function compute(v){const r=(fee,ac)=>v.p-v.c-v.p*fee/100-v.s-ac;const a=r(v.f1,0),b=r(v.f2,0),m=r(v.g,v.a);return tbl(['القناة','الربح للطلب','الهامش'],[['المنصة A',f(a),f(a/v.p*100,1)+'%'],['المنصة B',f(b),f(b/v.p*100,1)+'%'],['متجرك (مع تكلفة الاكتساب)',f(m),f(m/v.p*100,1)+'%']])+rec(['المنصات تجلب زبائن جاهزين لكنها تأخذ عمولة؛ متجرك يملك العميل لكن يتحمل الاكتساب.','وزّع القنوات: منصة للوصول، متجرك لبناء قاعدة عملائك.','أضف إلى متجرك ولاءً لخفض تكلفة الاكتساب للمشتري المتكرر.'])}''')

add('dropshipping-simulator', 'ecom', '📦', 'محاكي الدروبشيبنج', 'هل المنتج يستحق؟ الربح مع الإعلان والمرتجعات.',
 [F('p', 'سعر البيع', 'n', 149), F('c', 'سعر المورد', 'n', 55), F('s', 'شحن المورد', 'n', 18), F('f', 'رسوم الدفع %', 'n', 3), F('a', 'تكلفة الإعلان لكل طلب (CPA)', 'n', 40), F('r', 'نسبة الإرجاع %', 'n', 8), F('o', 'طلبات شهريًا', 'n', 300)],
 r'''function compute(v){const per=v.p-v.c-v.s-v.p*v.f/100-v.a-v.p*v.r/100*0.6;return kpis([kpi('ربح الطلب',f(per),per>0?'good':'bad'),kpi('ربح الشهر',f(per*v.o),per>0?'good':'bad'),kpi('الهامش',f(per/v.p*100,1)+'%'),kpi('أقصى CPA للتعادل',f(v.p-v.c-v.s-v.p*v.f/100-v.p*v.r/100*0.6))])+rec([per<0?'المنتج خاسر بهذه الفروض: ارفع السعر أو خفض CPA.':'اختبر المنتج بميزانية صغيرة قبل التوسع.','تحقق من جودة المورد وزمن الشحن بطلب تجريبي.','الإرجاع في الدروبشيبنج مكلف: وضح السياسة بصراحة.'])}''')

add('review-reply-generator', 'ecom', '⭐', 'مولّد الرد على تقييمات العملاء', 'ردود محترمة وتسويقية على تقييمات إيجابية وسلبية.',
 [S('k', 'نوع التقييم', [('good', '5 نجوم'), ('mid', '3 نجوم'), ('bad', 'نجمة أو نجمتان')]), F('n', 'اسم العميل', 'text', 'سارة'), F('s', 'اسم متجرك', 'text', 'متجر نسمة'), F('t', 'نص التقييم', 'textarea', 'المنتج جميل لكن التوصيل تأخر', r=3)],
 r'''function compute(v){const M={good:'شكرًا '+v.n+' على كلمتك الجميلة! سعدنا أن المنتج أعجبك. نحن في '+v.s+' نعتز بثقتك وننتظر طلبك القادم.',mid:'شكرًا '+v.n+' على رأيك الصادق. نقدّر ملاحظتك ("'+v.t.slice(0,60)+'") ونعمل على تحسينها. تواصل معنا لنخدمك بشكل أفضل.',bad:'نعتذر '+v.n+' عن تجربتك. ملاحظتك مهمة لنا ونود حل المشكلة فورًا. تواصل معنا عبر [قناة] برقم طلبك وسنعالجها خلال 24 ساعة. فريق '+v.s};return '<pre class="tpl" id="pr">'+esc(M[v.k])+'</pre>'+rec(['رد على كل التقييمات السلبية خلال 24 ساعة.','لا تجادل العميل علنًا؛ انقل الحل للخاص.','استخرج من التقييمات تحسينات للمنتج.'])+aiOut('اكتب ردًا مهنيًا ودودًا من 40 كلمة باسم متجر '+v.s+' على هذا التقييم من العميل '+v.n+': '+v.t+'. اعتذر إن لزم، وقدّم حلًا محددًا، دون وعود خارج السياسة.')}''', ai=True)

add('product-photo-brief', 'ecom', '📷', 'موجز تصوير المنتج', 'قائمة لقطات ووصف جاهز للمصور أو أداة الصور.',
 [F('p', 'المنتج', 'text', 'عطر عربي فاخر'), F('a', 'الجمهور', 'text', 'نساء 25-40'), F('s', 'الأسلوب', 'text', 'أنيق وهادئ'), F('b', 'خلفية/ألوان العلامة', 'text', 'بيج وذهبي')],
 r'''function compute(v){const L=['صورة المنتج على خلفية بيضاء (للمنصات)','صورة المنتج في بيئة استخدام: '+v.s,'لقطة قريبة للتفاصيل والخامة','صورة بالمقياس مع يد/جسم لإظهار الحجم','صورة التغليف والمحتويات','لقطة قبل/بعد أو فكرة الاستخدام','صورة غلاف للإعلان بألوان '+v.b];return '<ol class="qs">'+L.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'+aiOut('اكتب وصفًا لتوليد صورة منتج احترافية: المنتج '+v.p+'، الجمهور '+v.a+'، الأسلوب '+v.s+'، ألوان '+v.b+'. اذكر الإضاءة والزاوية والخلفية والتركيب. أعطني 3 أوصاف.')+rec(['صوّر بإضاءة طبيعية قدر الإمكان.','وحّد الخلفيات لتبدو هوية متجرك.','أضف صورة بالجوال بالمقياس ليثق العميل.'])}''', ai=True)

add('customer-lifetime-planner', 'ecom', '♾️', 'مخطط قيمة العميل مدى الحياة وسقف الإعلان', 'كم تنفق لاكتساب عميل جديد وتبقى رابحًا؟',
 [F('o', 'متوسط قيمة الطلب', 'n', 180), F('m', 'هامش الربح %', 'n', 35), F('f', 'عدد الطلبات للعميل سنويًا', 'n', 2.2), F('y', 'سنوات العلاقة', 'n', 2), F('t', 'نسبة الربح المسموح بإنفاقها على الاكتساب %', 'n', 40)],
 r'''function compute(v){const ltv=v.o*v.m/100*v.f*v.y,cap=ltv*v.t/100,first=v.o*v.m/100;return kpis([kpi('قيمة العميل (ربح)',f(ltv),'good'),kpi('سقف تكلفة الاكتساب',f(cap)),kpi('ربح أول طلب',f(first)),kpi('الطلب الأول وحده يغطي؟',first>=cap?'نعم':'لا',first>=cap?'good':'bad')])+rec(['إن كان الطلب الأول لا يغطي الاكتساب فاعتمد على المتابعة والولاء لاسترداده.','ارفع تكرار الشراء: بريد، واتساب، برنامج نقاط.','راقب CAC شهريًا مقابل هذا السقف.'])}''')
